/* collapses a .card-list from a grid table into standalone stacked cards, once its
   containing .section drops below \$width */

.workers-table {
    max-width: 800px;
    grid-template-columns:
        minmax(140px, 1fr)   /* worker id */
        minmax(90px, 1fr)    /* type */
        minmax(110px, 1fr)   /* status */
        minmax(220px, 2fr);  /* actions */
}

@container (max-width: 650px) {
        .workers-table {
            display: block;
            border: 0;
            background-color: transparent;
            max-width: none;
        }
        .workers-table > div:first-of-type {
            display: none;
        }
        .workers-table .row-group {
            display: block;
            border: var(--border-width) solid var(--mantine-color-default-border);
            border-radius: var(--mantine-radius-md);
        }
        .workers-table .row-group + .row-group {
            border-top: var(--border-width) solid var(--mantine-color-default-border);
            margin-top: 10px;
        }
        .workers-table .card {
            display: flex;
            flex-wrap: wrap;
            flex-direction: row;
            gap: 15px;
            border-left-width: 4px;
            justify-content: space-evenly;
        }

            .workers-table .card > div:last-of-type {
                flex-grow: 1;
            }
