        minmax(140px, 1fr)   /* total iter */
        minmax(200px, 1fr);  /* actions */
}

@container (max-width: 900px) {
        .jobs-table {
            display: block;
            border: 0;
            background-color: transparent;
            max-width: none;
        }
        .jobs-table > div:first-of-type {
            display: none;
        }
