        .jobs-table .row-group + .row-group {
            border-top: var(--border-width) solid var(--mantine-color-default-border);
            margin-top: 10px;
        }
        .jobs-table .card {
            display: flex;
            flex-wrap: wrap;
            flex-direction: row;
            gap: 15px;
            border-left-width: 4px;
            justify-content: space-evenly;
        }

            .jobs-table .card > div:last-of-type {
                flex-grow: 1;
            }
    }

/* wraps a .card + its .card-body Collapse, so rows can be divided/gapped as units */
.row-group {
    display: grid;
    grid-template-columns: subgrid;
    grid-column: 1 / -1;
}

.row-group + .row-group {
    border-top: var(--border-width) solid var(--mantine-color-default-border);
}

.card {
    display: grid;
    grid-template-columns: subgrid;
    grid-column: 1 / -1;
    align-items: center;

    padding: 10px;
    cursor: pointer;
    border-left: 3px solid var(--status, transparent);
}

.card:hover {
        background-color: var(--mantine-color-default-hover);
    }

.card-body {
    grid-column: 1 / -1;
    padding: 0 20px 20px 13px;
    /*color: var(--mantine-color-dimmed);*/
    border-left: 3px solid var(--status, transparent);
}

.progress-wrap {
    display: flex;
    align-items: center;
    gap: 8px;
}

.status {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-weight: 600;
    color: var(--status);
}

.status::before {
        content: "";
        width: 6px;
        height: 6px;
        border-radius: 50%;
        background-color: currentColor;
    }


